('b25f6e06-f5b9-443d-8919-319caf447ec4','{"val_partido":"2. BAJA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_INTERIOR":"Volante interior de bastante despliegue por todo el mediocampo, pero con poca profundidad para ejercer pases o causar sorpresa en fase ofensiva, ya tuvo su paso por el fútbol ecuatoriano anteriormente, y por ser jóven habrá que seguir observando más adelante, pero sin ser prioridad en el mercado.","car_obs_interior":"Volante interior de bastante despliegue por todo el mediocampo, pero con poca profundidad para ejercer pases o causar sorpresa en fase ofensiva, ya tuvo su paso por el fútbol ecuatoriano anteriormente, y por ser jóven habrá que seguir observando más adelante, pero sin ser prioridad en el mercado."}'),
('b80017ed-b706-4295-a339-7cab20bdf821','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"Gran lectura para recuperar balones, bueno distribuyendo la pelota y orientando las jugadas,","car_obs_mediocentro":"Gran lectura para recuperar balones, bueno distribuyendo la pelota y orientando las jugadas,"}'),
